import { readFile, writeFile } from 'node:fs/promises';
const prompt = await readFile(
  new URL('../docs/flowise-system-prompt.txt', import.meta.url),
  'utf8',
);
const itineraryPrompt = await readFile(new URL('../docs/flowise-itinerary-system-prompt.txt', import.meta.url), 'utf8');
await writeFile(
  new URL('../lib/model-system-prompt.ts', import.meta.url),
  '// Generated by scripts/sync-model-prompt.mjs; do not edit directly.\n' +
    `export const modelSystemPrompt = ${JSON.stringify(prompt)};\n` +
    `export const itinerarySystemPrompt = ${JSON.stringify(itineraryPrompt)};\n`,
);
